@app.command("locks", help="List lock files and optionally clear them after confirmation.")
def locks(
    clear_stale: Annotated[bool, typer.Option("--clear-stale", help="Clear lock files.")] = False,
    yes: Annotated[bool, typer.Option("--yes", help="Confirm clearing lock files.")] = False,
) -> None:
    def _run() -> None:
        paths = current_paths()
        paths.locks_dir.mkdir(parents=True, exist_ok=True)
        lock_infos = []
        cleared = []
        for path in sorted(paths.locks_dir.glob("*.lock")):
            try:
                metadata = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                metadata = {"lock_file": str(path)}
            lock_infos.append({"path": str(path), "metadata": metadata})
            if clear_stale and yes:
                path.unlink(missing_ok=True)
                cleared.append(str(path))
        emit_success(
            "doctor.locks",
            {
                "locks": lock_infos,
                "clear_stale": clear_stale,

"cleared": cleared,
                "dry_run": clear_stale and not yes,
            },
        )

def guess_media_type(path: Path) -> str:
    guessed, _encoding = mimetypes.guess_type(path.name)
    if guessed:
        return guessed
    if path.suffix.lower() in TEXT_EXTENSIONS:
        return "text/plain"
    return "application/octet-stream"

def extract_ranges(path: Path, source_id: str, source_fingerprint: str) -> list[SourceRangeRecord]:
    media_type = guess_media_type(path)
    if path.suffix.lower() == ".json":
        try:
            return _extract_structured_ranges(
                json.loads(path.read_text(encoding="utf-8-sig")),
                source_id,
                source_fingerprint,
            )
        except Exception:
            return _extract_text_ranges(path, source_id, source_fingerprint)
    if path.suffix.lower() in {".yaml", ".yml"}:
        try:
            return _extract_structured_ranges(
                yaml.safe_load(path.read_text(encoding="utf-8-sig")),
                source_id,
                source_fingerprint,
            )
        except Exception:
            return _extract_text_ranges(path, source_id, source_fingerprint)
    if path.suffix.lower() == ".toml":
        try:
            return _extract_structured_ranges(
                tomllib.loads(path.read_text(encoding="utf-8-sig")),

source_id,
                source_fingerprint,
            )
        except Exception:
            return _extract_text_ranges(path, source_id, source_fingerprint)
    if path.suffix.lower() == ".csv":
        try:
            return _extract_csv_ranges(path, source_id, source_fingerprint)
        except Exception:
            return _extract_text_ranges(path, source_id, source_fingerprint)
    if not is_text_like(path, media_type):
        return []
    return _extract_text_ranges(path, source_id, source_fingerprint)

def _range_id(source_id: str, locator: Locator) -> str:
    digest = hashlib.sha256(
        f"{source_id}:{locator.model_dump_json(exclude_none=True)}".encode()
    ).hexdigest()
    return f"rng_{digest[:26].upper()}"

