def run[T](command: str, func: Callable[[], T]) -> T:
    try:
        return func()
    except SystemExit:
        raise
    except KcError as exc:
        emit_error(command, exc)
    except Exception as exc:
        emit_unexpected(command, exc)
    raise AssertionError("unreachable")

